<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | Edit Staff</title><?= view('partials/styles') ?></head><body><div class="app-shell"><?= view('partials/nav', ['active' => 'users']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Access management</p><h1>Edit staff account</h1><p class="subtitle">Update staff details, role, password, or avatar.</p></div><div class="profile"><div class="avatar">AD</div> Admin account</div></header><section class="panel"><?php if (session()->getFlashdata('error')): ?><div class="form-error"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?><form action="<?= base_url('users/update/' . $user['id']) ?>" method="post" enctype="multipart/form-data"><div class="form-grid"><div class="field"><label for="username">Username</label><input class="input" id="username" name="username" value="<?= esc($user['username']) ?>" required></div><div class="field"><label for="full_name">Full name</label><input class="input" id="full_name" name="full_name" value="<?= esc($user['full_name']) ?>" required></div><div class="field"><label for="role">Role</label><select class="input" id="role" name="role"><?php foreach (['Staff','Cashier','Manager','Administrator'] as $role): ?><option <?= ($user['role'] ?? 'Staff') === $role ? 'selected' : '' ?>><?= $role ?></option><?php endforeach; ?></select></div><div class="field"><label for="password">New password (optional)</label><input class="input" type="password" id="password" name="password" minlength="6"></div><div class="field full"><label for="avatar">Replace avatar</label><input class="input" type="file" id="avatar" name="avatar" accept=".jpg,.jpeg,.png"></div><?php if (!empty($user['avatar'])): ?><div class="field full"><label>Current avatar</label><img class="current-image" src="<?= base_url('uploads/avatars/' . $user['avatar']) ?>" alt="Current avatar"></div><?php endif; ?></div><div class="form-actions"><button class="button" type="submit">Update staff account</button><a class="button secondary" href="<?= base_url('users') ?>">Cancel</a></div></form></section></main></div></body></html>
